@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService
@inject NavigationManager Navigation
@rendermode InteractiveServer

<PageTitle>Courses - University Course Catalog</PageTitle>

<div class="container mt-4">
    <h1 class="mb-4">Course Catalog</h1>

    <div class="row mb-4">
        <div class="col-md-6 mb-2">
            <input type="text" class="form-control" placeholder="Search by title, code, or instructor..."
                   @bind="SearchTerm" @bind:event="oninput" />
        </div>
        <div class="col-md-4 mb-2">
            <select class="form-select" @bind="SelectedDepartmentId">
                <option value="0">All Departments</option>
                @foreach (var dept in CatalogService.GetDepartments())
                {
                    <option value="@dept.Id">@dept.Name</option>
                }
            </select>
        </div>
    </div>

    @{
        var courses = CatalogService.GetCourses(SearchTerm, SelectedDepartmentId > 0 ? SelectedDepartmentId : null);
    }

    @if (!courses.Any())
    {
        <div class="alert alert-info">No courses found matching your criteria.</div>
    }
    else
    {
        <div class="row">
            @foreach (var course in courses)
            {
                <div class="col-md-6 col-lg-4 mb-4">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@course.Title</h5>
                            <h6 class="card-subtitle mb-2 text-muted">@course.CourseCode</h6>
                            <p class="card-text mb-1"><small><strong>Department:</strong> @course.DepartmentName</small></p>
                            <p class="card-text mb-1"><small><strong>Credits:</strong> @course.Credits</small></p>
                            <p class="card-text mb-1"><small><strong>Instructor:</strong> @course.InstructorName</small></p>
                            <p class="card-text"><small><strong>Schedule:</strong> @course.Schedule</small></p>
                        </div>
                        <div class="card-footer bg-transparent">
                            <a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">View Details</a>
                        </div>
                    </div>
                </div>
            }
        </div>
        <p class="text-muted">Showing @courses.Count course(s)</p>
    }
</div>

@code {
    private string? SearchTerm { get; set; }
    private int SelectedDepartmentId { get; set; }

    protected override void OnInitialized()
    {
        var uri = new Uri(Navigation.Uri);
        var query = System.Web.HttpUtility.ParseQueryString(uri.Query);
        if (int.TryParse(query["departmentId"], out var deptId))
        {
            SelectedDepartmentId = deptId;
        }
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService
@inject NavigationManager Navigation
@rendermode InteractiveServer

<PageTitle>Enrollment Request - University Course Catalog</PageTitle>

<div class="container mt-4">
    <h1 class="mb-4">Enrollment Request</h1>
    <p class="text-muted mb-4">Fill out the form below to submit an enrollment request. All fields are required.</p>

    @if (Submitted)
    {
        <div class="alert alert-success">
            <h4 class="alert-heading">Request Submitted!</h4>
            <p>Thank you, <strong>@Model.FullName</strong>. Your enrollment request for
                <strong>@CatalogService.GetCourse(Model.CourseId)?.Title</strong> has been received.</p>
            <hr>
            <p class="mb-0">You will receive a confirmation via your university email.</p>
        </div>
        <a href="/" class="btn btn-outline-primary">Return Home</a>
    }
    else
    {
        <div class="row">
            <div class="col-lg-6">
                <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                    <DataAnnotationsValidator />
                    <ValidationSummary class="text-danger mb-3" />

                    <div class="mb-3">
                        <label for="fullName" class="form-label">Full Name</label>
                        <InputText id="fullName" class="form-control" @bind-Value="Model.FullName" />
                        <ValidationMessage For="() => Model.FullName" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="studentId" class="form-label">Student ID</label>
                        <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" placeholder="e.g., CS123456" />
                        <ValidationMessage For="() => Model.StudentId" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="courseSelect" class="form-label">Course</label>
                        <InputSelect id="courseSelect" class="form-select" @bind-Value="Model.CourseId">
                            <option value="0">-- Select a course --</option>
                            @foreach (var course in CatalogService.GetCourses())
                            {
                                <option value="@course.Id">@course.CourseCode - @course.Title</option>
                            }
                        </InputSelect>
                        <ValidationMessage For="() => Model.CourseId" class="text-danger" />
                    </div>

                    <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                </EditForm>
            </div>
        </div>
    }
</div>

@code {
    private EnrollmentRequest Model { get; set; } = new();
    private bool Submitted { get; set; }

    protected override void OnInitialized()
    {
        var uri = new Uri(Navigation.Uri);
        var query = System.Web.HttpUtility.ParseQueryString(uri.Query);
        if (int.TryParse(query["courseId"], out var courseId))
        {
            Model.CourseId = courseId;
        }
    }

    private void HandleSubmit()
    {
        CatalogService.SubmitEnrollment(Model);
        Submitted = true;
    }
}

